"""Pages of invoices."""


def page_count(n_items, page_size):
    """Return how many pages are needed to show n_items, page_size to a page."""
    return n_items // page_size


def page(invoices, number, page_size):
    """Return page `number` of invoices. Pages are numbered from 1."""
    start = (number - 1) * page_size
    return invoices[start:start + page_size]


def all_pages(invoices, page_size):
    """Return every page of invoices, in order."""
    return [page(invoices, n, page_size) for n in range(1, page_count(len(invoices), page_size) + 1)]


def client_names(invoices):
    """Return the distinct client values, in first-seen order."""
    names = []
    for x in invoices:
        if x.client not in names:
            names.append(x.client)
    return names

